if (msg.temperature == null) {
  return ['Ignore'];
}
var temp = Number(msg.temperature);
if (temp > 32) {
  return ['HighTemp'];
}
if (temp <= 30) {
  return ['NormalTemp'];
}
return ['Hysteresis'];

